const items = $input.all();
const isEmpty = !items || items.length === 0 || (items.length === 1 && (!items[0].json || Object.keys(items[0].json).length === 0));
if (isEmpty) {
  const wanted = $('Config').first().json['Topic Title'];
  throw new Error(`No topic found titled "${wanted}". It must exactly match a topic already created in Phase 1.`);
}
const topic = items[0].json;
return [{ json: { topic_id: topic.id, topic_title: topic.title, channel_id: topic.channel_id } }];

const items = $input.all();
const isEmpty = !items || items.length === 0 || (items.length === 1 && (!items[0].json || Object.keys(items[0].json).length === 0));
if (isEmpty) {
  throw new Error('No video with qc_passed_at set found for this topic. Run Phase 5 (phase5-qc.json) and get an overall_pass first.');
}
const video = items[0].json;
if (video.youtube_video_id) {
  throw new Error(`This video already has a youtube_video_id (${video.youtube_video_id}) — it looks like it was already published. Aborting rather than re-uploading a duplicate.`);
}
if (!video.render_url) {
  throw new Error('This video has no render_url — Phase 4 (Assembly) must complete first.');
}
return [{ json: { id: video.id, channel_id: video.channel_id, render_url: video.render_url } }];

const items = $input.all();
const isEmpty = !items || items.length === 0 || (items.length === 1 && (!items[0].json || Object.keys(items[0].json).length === 0));
if (isEmpty) {
  throw new Error('No seo_metadata row found for this video. Run Phase 8 (phase8-publishing.json) first.');
}
const seo = items[0].json;
return [{ json: seo }];

const items = $input.all();
const isEmpty = !items || items.length === 0 || (items.length === 1 && (!items[0].json || Object.keys(items[0].json).length === 0));
if (isEmpty) {
  throw new Error('No queued publish_jobs row (target: long_form) found for this video. Either Phase 8 never ran for it, or it was already picked up.');
}
return [{ json: { publish_job_id: items[0].json.id } }];

const items = $input.all();
const isEmpty = !items || items.length === 0 || (items.length === 1 && (!items[0].json || Object.keys(items[0].json).length === 0));
if (isEmpty) {
  throw new Error('Channel not found — data inconsistency, check the videos/channels tables.');
}
const channel = items[0].json;
if (!channel.youtube_channel_id) {
  throw new Error('This channel has no youtube_channel_id set. Complete YOUTUBE-OAUTH-SETUP.md step 7 first.');
}
return [{ json: { youtube_channel_id: channel.youtube_channel_id } }];

const resp = $input.first().json;
const headers = resp.headers || {};
const uploadUrl = headers.location || headers.Location;
if (!uploadUrl) {
  throw new Error('YouTube did not return a resumable upload Location header. Full response: ' + JSON.stringify(resp).slice(0, 500));
}
return [{ json: { upload_url: uploadUrl }, binary: $('Compute Binary Size').first().binary }];

const resp = $input.first().json;
if (!resp.id) {
  throw new Error('YouTube upload did not return a video id. Full response: ' + JSON.stringify(resp).slice(0, 500));
}
return [{ json: { youtube_video_id: resp.id } }];

const youtubeId = $('Parse Upload Result').first().json.youtube_video_id;
return [{ json: {
  result: 'Uploaded to YouTube as PRIVATE. Review it and flip it public yourself in YouTube Studio.',
  youtube_video_id: youtubeId,
  youtube_studio_url: `https://studio.youtube.com/video/${youtubeId}/edit`,
  video_id: $('Pick Video Row').first().json.id
} }];
